# Reconcile the two known local pilot summaries without asserting enterprise identity.
args <- commandArgs(trailingOnly=TRUE)
if(length(args)!=2L || !file.exists(args[1]) || file.exists(args[2]) || !dir.exists(dirname(args[2]))) stop('Supply an EXISTING database and a NEW database path in an existing directory.')
source('dev/scripts/duckdb-copy-checkpoint.R',local=TRUE)
copy_checkpointed_database(args[1],args[2])
con <- DBI::dbConnect(duckdb::duckdb(),dbdir=args[2])
tryCatch({
  sql <- paste(readLines('dev/schemas/duckdb-plan-reconciliation.sql',warn=FALSE),collapse='\n')
  statements <- trimws(strsplit(sql,';',fixed=TRUE)[[1]])
  DBI::dbWithTransaction(con,{
    source_hash <- DBI::dbGetQuery(con,"SELECT v.sha256 AS prototype_hash,p.source_sha256 AS worksheet_hash FROM source_version v CROSS JOIN research_register.plan_extraction p WHERE v.source_version_id=4 AND p.plan_id='steamboat-feasibility'")
    if(nrow(source_hash)!=1L || source_hash$prototype_hash!=source_hash$worksheet_hash) stop('Feasibility source versions do not match.')
    obj <- DBI::dbGetQuery(con,"SELECT o.objective_text,p.normalized_text FROM project_objective o CROSS JOIN research_register.plan_objective p WHERE o.objective_id=3 AND p.objective_id='SI-O3'")
    cri <- DBI::dbGetQuery(con,"SELECT c.criterion_text,p.summary,t.target_year,t.operator_as_reported,t.reference_text FROM performance_criterion c CROSS JOIN research_register.plan_criterion p JOIN research_register.plan_target t ON t.criterion_id=p.criterion_id WHERE c.criterion_id=1 AND p.criterion_id='SI-C04'")
    if(nrow(obj)!=1L || nrow(cri)!=1L || !identical(obj$objective_text,'Island restoration and protection: restore 50% of lost island acreage/topography and protect it from erosion') || !identical(cri$criterion_text,'At 10 years, affected island acreage is not less than as-built acreage') || !identical(cri$summary,'At 10 years, affected island acreage is not less than as-built acreage.') || cri$target_year!=10 || cri$operator_as_reported!='>=' || cri$reference_text!='as-built acreage') stop('Pilot or extracted records changed; review before proposing a mapping.')
    if(DBI::dbGetQuery(con,"SELECT count(*) n FROM research_register.plan_objective_passage e JOIN research_register.plan_passage p ON p.passage_id=e.passage_id WHERE e.objective_id='SI-O3' AND p.pdf_page=81")$n!=1 || DBI::dbGetQuery(con,"SELECT count(*) n FROM research_register.plan_criterion_passage e JOIN research_register.plan_passage p ON p.passage_id=e.passage_id WHERE e.criterion_id='SI-C04' AND p.pdf_page=703")$n!=1) stop('Expected supporting page locators missing.')
    for(s in statements[nzchar(statements)]) DBI::dbExecute(con,s)
    DBI::dbExecute(con,"INSERT INTO objective_plan_reconciliation VALUES (3, 'SI-O3', 'prototype summarizes worksheet objective', 'analyst-proposed', 'Same feasibility version and source page 81.','Prototype omits the 1950s baseline, project-area scope and measurement in acres; do not treat the wording as interchangeable.', ?, ?)",params=list(obj$objective_text,obj$normalized_text))
    DBI::dbExecute(con,"INSERT INTO criterion_plan_reconciliation VALUES (1, 'SI-C04', 'prototype summarizes worksheet criterion', 'analyst-proposed', 'Same feasibility version and source page 703.','Worksheet scope names individual locations; no attainment or EMMA identity is established.', ?, ?)",params=list(cri$criterion_text,cri$summary))
    if(DBI::dbGetQuery(con,'SELECT count(*) n FROM plan_reconciliation_issues')$n!=0) stop('Reconciliation integrity check failed.')
  })
  print(DBI::dbGetQuery(con,'SELECT objective_id,plan_objective_id,record_status FROM plan_objective_comparison'))
  print(DBI::dbGetQuery(con,'SELECT criterion_id,plan_criterion_id,record_status FROM plan_criterion_comparison'))
},finally=DBI::dbDisconnect(con,shutdown=TRUE))
cat(normalizePath(args[2],winslash='/'),'\n')
